  quiz: [["A unibody vehicle has:", ["A separate frame", "Body and frame as one unit", "No frame", "A wooden frame"], 1, "Unibody vehicles integrate body and frame."], ["Why follow OEM repair procedures?", ["They’re faster", "They keep repairs safe and correct", "They’re optional", "They reduce paint use"], 1, "Manufacturer procedures protect structural integrity."], ["Blending paint means:", ["Mixing colors", "Fading new paint into adjacent panels", "Removing paint", "Sanding primer"], 1, "Blending makes color matches invisible."], ["Which PPE is critical when spraying isocyanate paints?", ["Hearing protection only", "Approved respirator", "Steel-toe boots only", "Nothing"], 1, "Isocyanates require respiratory protection."], ["A supplement is:", ["A vitamin", "An additional estimate for hidden damage", "A paint additive", "A type of weld"], 1, "Supplements cover damage found after teardown."]],
