  steps: [["Build mechanical skills", "Shop classes, farm work or vehicle repair help."], ["Train in a diesel or heavy equipment program", "Learn hydraulics, engines and electrical systems."], ["Start as an apprentice or shop tech", "Work with experienced mechanics."], ["Earn certifications", "Add manufacturer and ASE credentials."], ["Advance", "Become a field technician, lead mechanic or service manager."]],
