  terms: [["Hydraulic system", "A system that uses pressurized fluid to move cylinders and motors."], ["Hydraulic pump", "Creates fluid flow in the system."], ["Cylinder", "A component that converts hydraulic pressure into straight-line motion."], ["Relief valve", "Protects the system by limiting maximum pressure."], ["Undercarriage", "The track, rollers, idlers and sprockets on tracked machines."], ["Final drive", "The gear reduction that powers tracks or wheels."], ["Powershift transmission", "A transmission that shifts under load."], ["ECM", "Electronic control module."], ["Fault code", "A diagnostic code stored by a machine’s computer."], ["Preventive maintenance (PM)", "Scheduled service to prevent breakdowns."], ["DEF", "Diesel exhaust fluid used in emissions systems."], ["DPF", "Diesel particulate filter."], ["Telematics", "Remote monitoring of machine data and location."], ["Swing drive", "The system that rotates an excavator’s upper structure."], ["Pilot controls", "Low-pressure hydraulic controls that operate main valves."]],
  howto: [
    { t: "Troubleshoot a Slow Hydraulic Function", intro: "Slow movement can come from the pump, valves, cylinders or fluid.", steps: ["Talk to the operator about when the problem occurs.", "Check fluid level, condition and filters.", "Inspect hoses and fittings for leaks or damage.", "Connect pressure gauges at test ports and compare with specs.", "Test pilot pressure and relief valve settings.", "Isolate the faulty component and repair or replace it."], tip: "Check the simple things first. Low fluid and plugged filters cause many hydraulic complaints." },
    { t: "Perform a Preventive Maintenance Service", intro: "Regular PM keeps expensive machines working and catches problems early.", steps: ["Review the machine’s service interval and history.", "Change engine oil and filters and take fluid samples.", "Replace fuel and air filters as scheduled.", "Grease all fittings.", "Inspect belts, hoses, undercarriage and safety devices.", "Record findings and recommend repairs."], tip: "Fluid analysis shows wear inside components before they fail." },
    { t: "Relieve Hydraulic Pressure Before Repairs", intro: "Stored hydraulic pressure can cause serious injection injuries.", steps: ["Lower all attachments to the ground.", "Shut off the engine and remove the key.", "Cycle controls to relieve pressure as the manual describes.", "Relieve tank pressure slowly.", "Block or support raised components.", "Loosen fittings slowly and keep your body clear."], tip: "Never check for leaks with your hand. Use cardboard; pinhole leaks can inject fluid into skin." }
  ],
  safety: ["Relieve hydraulic pressure before opening lines", "Block raised equipment and never work under unsupported loads", "Follow lockout/tagout procedures", "Wear PPE and stay clear of pinch points"],
  iq: [["How do you troubleshoot hydraulic problems?", "Walk through a systematic process."], ["What machines have you worked on?", "Name types and brands."], ["Are you comfortable working alone at job sites?", "Show independence and safety focus."], ["How do you prioritize multiple breakdowns?", "Mention safety, downtime cost and communication."], ["How do you use diagnostic software?", "Describe tools you’ve used."]],
