  quiz: [["A hydraulic relief valve:", ["Increases flow", "Limits maximum pressure", "Cools fluid", "Filters fluid"], 1, "Relief valves protect against overpressure."], ["How should you check for a pinhole hydraulic leak?", ["With your hand", "With cardboard", "With your face", "By listening"], 1, "Use cardboard to avoid injection injuries."], ["Undercarriage parts include:", ["Pistons", "Track rollers and idlers", "Fuel injectors", "Spark plugs"], 1, "Tracks, rollers, idlers and sprockets."], ["Fluid analysis helps detect:", ["Paint wear", "Internal component wear", "Tire pressure", "Fuel prices"], 1, "Oil samples reveal wear metals."], ["Before working under a raised boom you must:", ["Hurry", "Block or support it", "Turn on the radio", "Add fuel"], 1, "Raised components must be supported."]],
